dtsPropsFor.Accordion:
/** Rótulo do cabeçalho. Sempre visível, aberto ou fechado. */
title: string;
/** Segunda linha do cabeçalho, para qualificar o título. */
description?: string;
/** Slug do ícone, à esquerda do título. Ver `Icon`. */
icon?: string;
/** Nasce aberto. Sem isso, fechado. */
defaultOpen?: boolean;
children?: React.ReactNode;

dtsPropsFor.Callout:
/** `info` é o neutro e o padrão. A inversão com `note` é deliberada. */
variant?: 'note' | 'info' | 'tip' | 'warning';
/** Primeira linha, em destaque. Sem ela o corpo começa direto. */
title?: string;
children?: React.ReactNode;

dtsPropsFor.Card:
/** Rótulo do cartão. */
title: string;
/** Slug do ícone, acima do título. Ver `Icon`. */
icon?: string;
/** Com `href` o cartão inteiro vira o link; sem ele, é uma superfície. */
href?: string;
children?: React.ReactNode;

dtsPropsFor.Expandable:
/** O texto do `<summary>`, a linha que abre e fecha. */
title: string;
/** Nível 1 abre por padrão; nível 2 e abaixo nascem fechados. */
defaultOpen?: boolean;
children?: React.ReactNode;

dtsPropsFor.ParamField:
/** Nome do parâmetro. Vira o id da âncora. */
name: string;
/** O tipo, como o leitor o escreveria. */
type: string;
/** Só o obrigatório é marcado; a ausência é o sinal de opcional. */
required?: boolean;
/** Risca o nome e apaga o texto. Sem cor: vermelho é do chip de obrigatório. */
deprecated?: boolean;
/** Valor padrão, num chip ao lado do tipo. */
default?: string;
children?: React.ReactNode;

dtsPropsFor.ResponseField:
/** Nome do campo da resposta. Vira o id da âncora. */
name: string;
/** O tipo, como o leitor o escreveria. */
type: string;
/** Só o obrigatório é marcado; a ausência é o sinal de opcional. */
required?: boolean;
/** Risca o nome e apaga o texto. Sem cor: vermelho é do chip de obrigatório. */
deprecated?: boolean;
/** Valor padrão, num chip ao lado do tipo. */
default?: string;
children?: React.ReactNode;

dtsPropsFor.Step:
/** Título do passo, acima do corpo. */
title?: string;
/** Um ícone SUBSTITUI o número — não senta ao lado dele. */
icon?: string;
children?: React.ReactNode;

dtsPropsFor.Table:
/** As linhas da tabela: `<thead>` e `<tbody>`. O componente é o `<table>` mais a região rolável que o torna alcançável pelo teclado. */
children?: React.ReactNode;
/** Todo o resto desce para o `<table>`. */
[prop: string]: unknown;

dtsPropsFor.Update:
/** A versão, ou a data. É o cabeçalho do registro. */
label: string;
/** Etiqueta ao lado do rótulo, para qualificar a entrada. */
tag?: string;
children?: React.ReactNode;
